//! G14 observe-port parity against the TS answers (`tests/spec/analytics-writers/vectors.json`,
//! regenerated by `generate-vectors.mjs`). Numbers compare by value, as the store's own serde
//! path reads them (an integral JSON number and its float spelling are one measurement).
use aac_store::observe;
use serde_json::{Map, Value};

fn vectors() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/spec/analytics-writers/vectors.json"
    );
    let text = std::fs::read_to_string(path).expect("vectors.json (run generate-vectors.mjs)");
    serde_json::from_str(&text).expect("vectors parse")
}

/// Every number as the f64 the store reads; object key order is kept (the whitelist's order).
fn numbers(value: &Value) -> Value {
    match value {
        Value::Number(n) => serde_json::json!(n.as_f64().expect("finite vector number")),
        Value::Array(list) => Value::Array(list.iter().map(numbers).collect()),
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(k, v)| (k.clone(), numbers(v)))
                .collect::<Map<String, Value>>(),
        ),
        other => other.clone(),
    }
}

fn optional(value: Option<impl serde::Serialize>) -> Value {
    match value {
        Some(v) => numbers(&serde_json::to_value(v).expect("serialize")),
        None => Value::Null,
    }
}

#[test]
fn windows_match_the_ts_whitelist() {
    let doc = vectors();
    for (index, case) in doc["windows"].as_array().expect("windows").iter().enumerate() {
        let input = &case["input"];
        let expected = numbers(&case["expected"]);
        let got = optional(observe::analytics_window(input));
        assert_eq!(got, expected, "window {index} whitelist");
        let stored = numbers(&case["stored"]);
        let got_stored = optional(observe::store_window(input));
        assert_eq!(got_stored, stored, "window {index} store shape");
        if let Some(safe) = observe::analytics_window(input) {
            assert_eq!(
                Value::String(observe::window_identity(&safe)),
                numbers(&case["identity"]),
                "window {index} identity"
            );
        }
    }
}

#[test]
fn accounts_match_the_ts_sampler() {
    let doc = vectors();
    for (index, case) in doc["accounts"].as_array().expect("accounts").iter().enumerate() {
        let now = case["now"].as_i64().expect("now");
        let retention = case["retentionMs"].as_i64().expect("retention");
        let expected = numbers(&case["expected"]);
        let got = optional(observe::observation_from_account(&case["account"], now, retention));
        assert_eq!(got, expected, "account {index} observation");
        let row = case["account"].as_object().expect("account object");
        assert_eq!(
            observe::account_identity(row).map(Value::String).unwrap_or(Value::Null),
            numbers(&case["identity"]),
            "account {index} identity"
        );
        assert_eq!(
            Value::String(observe::source_platform(row)),
            numbers(&case["platform"]),
            "account {index} platform"
        );
    }
}

#[test]
fn records_match_the_ts_backfill() {
    let doc = vectors();
    for (index, case) in doc["records"].as_array().expect("records").iter().enumerate() {
        let decoded = observe::decode_observation(&case["record"]);
        match (&decoded, case["decoded"].is_null()) {
            (None, true) => {}
            (Some(_), true) => panic!("record {index}: TS refused, port decoded"),
            (None, false) => panic!("record {index}: TS decoded, port refused"),
            (Some(got), false) => {
                let want = &case["decoded"];
                assert_eq!(Value::String(got.identity.clone()), numbers(&want["identity"]));
                assert_eq!(Value::String(got.account_id.clone()), numbers(&want["accountId"]));
                assert_eq!(Value::String(got.sampled_at.clone()), numbers(&want["sampledAt"]));
                assert_eq!(Value::String(got.observed_at.clone()), numbers(&want["observedAt"]));
                assert_eq!(Value::String(got.platform.clone()), numbers(&want["platform"]));
                assert_eq!(Value::String(got.source.clone()), numbers(&want["source"]));
                assert_eq!(Value::String(got.status.clone()), numbers(&want["status"]));
                assert_eq!(Value::Bool(got.is_active), numbers(&want["isActive"]));
                let windows = Value::Array(got.windows.iter().map(|w| Value::Object(w.clone())).collect());
                assert_eq!(numbers(&windows), numbers(&want["windows"]), "record {index} windows");
            }
        }
        let expected = numbers(&case["expected"]);
        let got = optional(decoded.as_ref().and_then(|d| {
            observe::observation_from_record(
                d,
                case["provider"].as_str().expect("provider"),
                case["importRef"].as_str().expect("importRef"),
            )
        }));
        assert_eq!(got, expected, "record {index} observation");
    }
}

#[test]
fn texts_match_the_ts_archive_shapes() {
    let doc = vectors();
    for (index, case) in doc["texts"].as_array().expect("texts").iter().enumerate() {
        let text = case["text"].as_str().expect("text");
        let (records, parsed) = observe::records_from_text(text);
        assert_eq!(Value::Bool(parsed), numbers(&case["parsed"]), "text {index} parsed");
        assert_eq!(
            numbers(&Value::Array(records)),
            numbers(&case["records"]),
            "text {index} records"
        );
    }
}

#[test]
fn timestamps_match_the_ts_normalization() {
    let doc = vectors();
    for (index, case) in doc["timestamps"].as_array().expect("timestamps").iter().enumerate() {
        let got = observe::analytics_timestamp(&case["value"])
            .map(Value::String)
            .unwrap_or(Value::Null);
        assert_eq!(got, numbers(&case["expected"]), "timestamp {index}");
    }
}
